//  EDIT THIS BLOCK (this "On Start" tab), THEN DEPLOY.
//  It runs on every deploy / restart.
// =====================================================================
const cfg = {
    // Charge window
    chargeHours: 3,                 // length of the charge window (hours it takes to fill the battery)
    targetSoc: 100,                 // SOC to charge to in the charge window
    priceProperty: 'all_in_with_vat', // EnergyZero price array to use
    refreshFromHour: 15,            // local hour from which tomorrow's prices are fetched

    // After the charge window: self-consume when price > charge price / roundTripEfficiency + b_cycle_cost,
    // otherwise hold the battery (no discharge, house on grid)
    b_cycle_cost: 0.01,             // battery cost per kWh cycled (EUR/kWh)
    roundTripEfficiency: 1,         // e.g. 0.85 to include charge/discharge losses
    minSoc: 10,                     // shown as target in self-consume hours (the GX ignores it there);
                                    //   set to your ESS minimum SOC so the plan graph is realistic

    // Battery, also written to the GX (Dynamic ESS settings)
    b_max: 10,                      // usable battery capacity (kWh)
    tb_max: 5,                      // max battery CHARGE power (kW): charge rate in the charge window
    fb_max: 5,                      // max battery DISCHARGE power (kW)
    feed_in_possible: true,         // allow solar feed-in to the grid (AllowGridFeedIn)

    // GX schedule slots
    scheduleSlots: 48,              // 48 on current Venus OS, 4 on older versions
    writeTargetSoc: true            // also write Schedule/N/TargetSoc (current Venus OS); false on older versions
};
context.set('cfg', cfg);
flow.set('cheapestHourDessConfig', cfg);
node.status({ fill: 'blue', shape: 'dot', text: 'config loaded' });

