// Ended windows are kept for 48 h: the rules planner uses their price as
// "what the energy in the battery cost".
function activeTarget(targets, nowMs) {
    const kept = {};
    let active = null;
    for (const [date, t] of Object.entries(targets || {})) {
        if (!t || !Number.isInteger(t.hour) || !t.end) continue;
        const end = Date.parse(t.end);
        if (end <= nowMs - 48 * 3600 * 1000) continue;
        kept[date] = t;
        if (end > nowMs && (!active || Date.parse(t.start) < Date.parse(active.start))) active = t;
