    if (!row || !row.start || !row.price || row.price.value === undefined || row.price.value === null) continue;
    const dt = new Date(row.start);
    if (Number.isNaN(dt.getTime())) continue;
    if (localYmd(dt) !== msg.priceDate) continue;   // response also contains the previous day
    const price = Number(row.price.value);
    if (!Number.isFinite(price)) continue;
    candidates.push({ start: row.start, end: row.end, price: price, hour: localHour(dt) });
