    let contiguous = true;
    for (let k = 1; k < block.length; k++) {
        if (Date.parse(block[k].start) - Date.parse(block[k - 1].start) !== 3600000) contiguous = false;
    }
    if (!contiguous) continue;
    const avg = block.reduce((s, c) => s + c.price, 0) / block.length;
    if (!best || avg < best.price - 1e-12) {
