// Reads what the Rules planner stored in flow context (cheapestHourDessPlan);
// nothing is written to the GX from here.
const cfg = flow.get('cheapestHourDessConfig') || {};
const stored = flow.get('cheapestHourDessPlan');
const targets = flow.get('cheapestHourDessTargets') || {};
const TZ = 'Europe/Amsterdam';
const H = 3600000;
const nowMs = Date.now();
const soc = flow.get('cheapestHourDessSoc');   // { value, at } from the "Battery SoC" node

// Only hours that have not ended yet (the plan is refreshed every hour).
const hours = stored && Array.isArray(stored.hours)
    ? stored.hours.filter(h => h.start + H > nowMs)
    : [];
const windows = Object.values(targets)
    .filter(t => t && t.start && t.end)
    .map(t => ({ date: t.date, start: t.start, end: t.end, price: t.price, hours: t.hours }))
    .sort((a, b) => Date.parse(a.start) - Date.parse(b.start));

if (msg.req && msg.req.query && msg.req.query.format === 'json') {
    msg.headers = { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' };
    msg.payload = { plannedAt: stored ? stored.plannedAt : null, now: nowMs, soc: soc || null, config: cfg, chargeWindows: windows, hours: hours };
    return msg;
}

const esc = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fmtHour = new Intl.DateTimeFormat('en-GB', { timeZone: TZ, hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
const fmtDay = new Intl.DateTimeFormat('en-GB', { timeZone: TZ, weekday: 'short', day: '2-digit', month: 'short' });
const fmtFull = new Intl.DateTimeFormat('en-GB', { timeZone: TZ, weekday: 'short', day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
const eur = v => (v === null || v === undefined) ? '–' : '€' + Number(v).toFixed(4);
const MODES = {
    charge: { label: 'Charge', desc: 'charge from grid to ' + (cfg.targetSoc || 100) + '%' },
    self:   { label: 'Self-consume', desc: 'battery covers the load, no export' },
    hold:   { label: 'Hold', desc: 'no discharge, grid covers the load' }
};

// ---------- chart (server-side SVG) ----------
let chart = '<p class="empty">No plan yet. Press <b>Run now (test)</b> in the flow, or wait for the next hourly run.</p>';
if (hours.length) {
    const W = 960, HGT = 300, padL = 56, padR = 12, padT = 16, padB = 44;
    const plotW = W - padL - padR, plotH = HGT - padT - padB;
    const vals = hours.map(h => h.price).concat(hours.filter(h => h.threshold !== null).map(h => h.threshold));
    let lo = Math.min(0, ...vals), hi = Math.max(...vals);
    // "nice" axis steps
    const rawStep = (hi - lo) / 4 || 0.05;
    const mag = Math.pow(10, Math.floor(Math.log10(rawStep)));
    const step = [1, 2, 2.5, 5, 10].map(m => m * mag).find(s => s >= rawStep);
    lo = Math.floor(lo / step) * step; hi = Math.ceil(hi / step) * step;
    if (hi === lo) hi = lo + step;
    const y = v => padT + plotH - (v - lo) / (hi - lo) * plotH;
    const colW = plotW / hours.length;
    const barW = Math.max(2, colW - 2);               // 2px surface gap between bars
    const r = Math.min(4, barW / 2);
    const x0 = i => padL + i * colW + (colW - barW) / 2;
    const parts = [];

    // grid + y labels
    for (let v = lo; v <= hi + step / 2; v += step) {
        const yy = y(v).toFixed(1);
        parts.push('<line class="grid" x1="' + padL + '" x2="' + (W - padR) + '" y1="' + yy + '" y2="' + yy + '"/>');
        parts.push('<text class="axis" x="' + (padL - 8) + '" y="' + yy + '" dy="0.32em" text-anchor="end">' + v.toFixed(2) + '</text>');
    }
    // midnight separators + x labels every 3 hours
    hours.forEach((h, i) => {
        const hh = fmtHour.format(new Date(h.start));
        const cx = padL + i * colW;
        if (hh === '00:00' && i > 0) {
            parts.push('<line class="day" x1="' + cx.toFixed(1) + '" x2="' + cx.toFixed(1) + '" y1="' + padT + '" y2="' + (padT + plotH) + '"/>');
            parts.push('<text class="axis day-label" x="' + (cx + 4).toFixed(1) + '" y="' + (padT + 10) + '">' + esc(fmtDay.format(new Date(h.start))) + '</text>');
        }
        if (i % 3 === 0) {
            parts.push('<text class="axis" x="' + (cx + colW / 2).toFixed(1) + '" y="' + (padT + plotH + 16) + '" text-anchor="middle">' + hh.slice(0, 2) + '</text>');
        }
    });
    // bars: rounded data end, square at the zero baseline
    const base = y(0);
    hours.forEach((h, i) => {
        const x = x0(i), top = y(h.price);
        const up = top <= base, len = Math.abs(base - top);
        const rr = Math.min(r, len);
        let d;
        if (len < 0.5) d = 'M' + x + ',' + base + 'h' + barW;
        else if (up) d = 'M' + x + ',' + base + 'V' + (top + rr) + 'Q' + x + ',' + top + ' ' + (x + rr) + ',' + top
            + 'H' + (x + barW - rr) + 'Q' + (x + barW) + ',' + top + ' ' + (x + barW) + ',' + (top + rr) + 'V' + base + 'Z';
        else d = 'M' + x + ',' + base + 'V' + (top - rr) + 'Q' + x + ',' + top + ' ' + (x + rr) + ',' + top
            + 'H' + (x + barW - rr) + 'Q' + (x + barW) + ',' + top + ' ' + (x + barW) + ',' + (top - rr) + 'V' + base + 'Z';
        parts.push('<path class="bar m-' + h.mode + (i === 0 ? ' now' : '') + '" d="' + d + '"/>');
    });
    parts.push('<line class="baseline" x1="' + padL + '" x2="' + (W - padR) + '" y1="' + base.toFixed(1) + '" y2="' + base.toFixed(1) + '"/>');
    // threshold as a step line (same unit and axis as the price)
    let tp = '';
    hours.forEach((h, i) => {
        if (h.threshold === null) { tp += ' '; return; }
        const yy = y(h.threshold).toFixed(1);
        const xa = (padL + i * colW).toFixed(1), xb = (padL + (i + 1) * colW).toFixed(1);
        tp += (tp.endsWith(' ') || !tp ? 'M' : 'L') + xa + ',' + yy + 'L' + xb + ',' + yy;
    });
    if (tp.trim()) parts.push('<path class="threshold" d="' + tp.trim().replace(/ +/g, ' ') + '"/>');
    // "now" marker
    const nowX = padL + Math.min(1, Math.max(0, (nowMs - hours[0].start) / H)) * colW;
    parts.push('<line class="nowline" x1="' + nowX.toFixed(1) + '" x2="' + nowX.toFixed(1) + '" y1="' + padT + '" y2="' + (padT + plotH) + '"/>');
    parts.push('<text class="axis" x="' + nowX.toFixed(1) + '" y="' + (padT + plotH + 32) + '" text-anchor="middle">now</text>');
    // hover targets: the full column, larger than the bar
    hours.forEach((h, i) => {
        const tip = fmtFull.format(new Date(h.start)) + '|' + MODES[h.mode].label + '|' + eur(h.price)
            + '|' + (h.threshold === null ? '' : eur(h.threshold)) + '|' + h.targetSoc;
        parts.push('<rect class="hit" x="' + (padL + i * colW).toFixed(1) + '" y="' + padT + '" width="' + colW.toFixed(1) + '" height="' + plotH + '" data-tip="' + esc(tip) + '"/>');
    });
    chart = '<svg viewBox="0 0 ' + W + ' ' + HGT + '" role="img" aria-label="Planned battery mode and price per hour">'
        + parts.join('') + '</svg>';
}

// ---------- summary + table ----------
const cur = hours.find(h => h.start <= nowMs && nowMs < h.start + H) || hours[0];
const counts = { charge: 0, self: 0, hold: 0 };
hours.forEach(h => counts[h.mode]++);
const next = windows.find(w => Date.parse(w.end) > nowMs);
const tiles = [
    ['Now', cur ? MODES[cur.mode].label : '–', cur ? MODES[cur.mode].desc : ''],
    ['Battery SoC', soc && soc.value !== null ? Number(soc.value).toFixed(0) + '%' : '–',
        !soc ? 'waiting for the GX' : (soc.value === null ? 'unknown since ' : 'last change ') + fmtHour.format(new Date(soc.at))],
    ['Price now', cur ? eur(cur.price) : '–', cur && cur.threshold !== null ? 'threshold ' + eur(cur.threshold) : ''],
    ['Next charge window', next ? fmtFull.format(new Date(next.start)) + ' – ' + fmtHour.format(new Date(next.end)) : 'none yet',
        next ? 'avg ' + eur(next.price) : 'tomorrow’s prices arrive in the afternoon'],
    ['Planned hours', String(hours.length), counts.charge + ' charge · ' + counts.self + ' self · ' + counts.hold + ' hold']
];
const rows = hours.map(h => '<tr class="' + (h === cur ? 'cur' : '') + '"><td>' + esc(fmtFull.format(new Date(h.start)))
    + '</td><td><span class="sw m-' + h.mode + '"></span>' + MODES[h.mode].label
    + '</td><td class="num">' + eur(h.price) + '</td><td class="num">' + eur(h.threshold)
    + '</td><td class="num">' + h.targetSoc + '%</td><td class="num">' + h.strategy + '/' + h.restrictions + '</td></tr>').join('');

msg.headers = { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' };
msg.payload = `<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta http-equiv="refresh" content="300">
<title>DESS schedule</title>
<style>
.viz-root{color-scheme:light;--surface-1:#fcfcfb;--surface-2:#f3f2ef;--text-primary:#0b0b0b;--text-secondary:#52514e;
  --grid:#e4e3df;--axis:#8a8984;--s-charge:#2a78d6;--s-self:#eb6834;--s-hold:#1baf7a}
@media (prefers-color-scheme:dark){.viz-root{color-scheme:dark;--surface-1:#1a1a19;--surface-2:#242422;--text-primary:#f0efec;
  --text-secondary:#c3c2b7;--grid:#33332f;--axis:#7d7c76;--s-charge:#3987e5;--s-self:#d95926;--s-hold:#199e70}}
html,body{margin:0}
body.viz-root{background:var(--surface-1);color:var(--text-primary);font:14px/1.4 system-ui,-apple-system,"Segoe UI",sans-serif}
main{max-width:1000px;margin:0 auto;padding:20px}
h1{font-size:20px;margin:0 0 2px}.sub{color:var(--text-secondary);margin:0 0 16px}
.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;margin-bottom:16px}
.tile{background:var(--surface-2);border-radius:8px;padding:10px 12px}
.tile .k{color:var(--text-secondary);font-size:12px}.tile .v{font-size:18px;font-weight:600}.tile .d{color:var(--text-secondary);font-size:12px}
.legend{display:flex;flex-wrap:wrap;gap:16px;color:var(--text-secondary);font-size:13px;margin:4px 0 6px}
.sw{display:inline-block;width:10px;height:10px;border-radius:2px;margin-right:6px;vertical-align:-1px}
.sw.line{height:0;border-top:2px dashed var(--text-secondary);border-radius:0;vertical-align:3px;width:16px}
.m-charge{fill:var(--s-charge);background:var(--s-charge)}.m-self{fill:var(--s-self);background:var(--s-self)}.m-hold{fill:var(--s-hold);background:var(--s-hold)}
.chart{position:relative}svg{width:100%;height:auto;display:block}
.grid{stroke:var(--grid);stroke-width:1}.baseline{stroke:var(--axis);stroke-width:1}
.day{stroke:var(--axis);stroke-width:1;stroke-dasharray:2 3}
.axis{fill:var(--text-secondary);font-size:11px}.day-label{font-weight:600}
.threshold{fill:none;stroke:var(--text-primary);stroke-width:2;stroke-dasharray:5 4;opacity:.7}
.nowline{stroke:var(--text-primary);stroke-width:1.5}
.hit{fill:transparent;cursor:crosshair}.hit:hover{fill:var(--text-primary);fill-opacity:.06}
.tip{position:absolute;pointer-events:none;background:var(--surface-1);color:var(--text-primary);border:1px solid var(--grid);
  border-radius:6px;padding:6px 8px;font-size:12px;box-shadow:0 2px 8px rgba(0,0,0,.15);white-space:nowrap;display:none}
.tip b{display:block}.tip .muted{color:var(--text-secondary)}
details{margin-top:16px}summary{cursor:pointer;color:var(--text-secondary)}
table{border-collapse:collapse;width:100%;margin-top:8px;font-size:13px}
th,td{padding:4px 8px;border-bottom:1px solid var(--grid);text-align:left}th{color:var(--text-secondary);font-weight:500}
td.num,th.num{text-align:right;font-variant-numeric:tabular-nums}tr.cur td{font-weight:600}
.empty{padding:40px;text-align:center;color:var(--text-secondary)}
footer{color:var(--text-secondary);font-size:12px;margin-top:16px}
</style></head>
<body class="viz-root"><main>
<h1>DESS schedule</h1>
<p class="sub">Planned ${stored ? esc(fmtFull.format(new Date(stored.plannedAt))) : '–'} · prices: EnergyZero ${esc(cfg.priceProperty || 'all_in_with_vat')} (EUR/kWh) · charge ${esc(cfg.chargeHours || 3)} h to ${esc(cfg.targetSoc || 100)}%</p>
<div class="tiles">${tiles.map(t => '<div class="tile"><div class="k">' + esc(t[0]) + '</div><div class="v">' + esc(t[1]) + '</div><div class="d">' + esc(t[2]) + '</div></div>').join('')}</div>
<div class="legend">
  <span><span class="sw m-charge"></span>Charge (${counts.charge} h)</span>
  <span><span class="sw m-self"></span>Self-consume (${counts.self} h)</span>
  <span><span class="sw m-hold"></span>Hold (${counts.hold} h)</span>
  <span><span class="sw line"></span>Self-consume threshold</span>
</div>
<div class="chart">${chart}<div class="tip" id="tip"></div></div>
<details${hours.length && hours.length <= 12 ? ' open' : ''}><summary>Table (${hours.length} hours)</summary>
<table><thead><tr><th>Hour</th><th>Mode</th><th class="num">Price</th><th class="num">Threshold</th><th class="num">Target SOC</th><th class="num">Strategy/Restr.</th></tr></thead>
<tbody>${rows}</tbody></table></details>
<footer>Read-only view of the plan in flow context; refreshes every 5 minutes. JSON: <a href="?format=json">?format=json</a></footer>
</main>
<script>
(function(){var tip=document.getElementById('tip'),box=document.querySelector('.chart');if(!box)return;
box.addEventListener('mousemove',function(e){var t=e.target;if(!t.dataset||!t.dataset.tip){tip.style.display='none';return;}
var p=t.dataset.tip.split('|'),b=box.getBoundingClientRect();
tip.innerHTML='<b>'+p[0]+'</b>'+p[1]+' · target '+p[4]+'%<br>price '+p[2]+(p[3]?'<br><span class="muted">threshold '+p[3]+'</span>':'');
tip.style.display='block';var x=e.clientX-b.left+12;if(x+tip.offsetWidth>b.width)x=e.clientX-b.left-tip.offsetWidth-12;
tip.style.left=x+'px';tip.style.top=(e.clientY-b.top+12)+'px';});
box.addEventListener('mouseleave',function(){tip.style.display='none';});})();
</script>
</body></html>`;
return msg;

// Latest battery SoC for the /dess page (read-only; not used by the planner).
// null/empty = the GX reports no valid SoC (e.g. battery monitor offline): store it as unknown, not 0.
const raw = msg.payload;
const v = (typeof raw === 'number' || (typeof raw === 'string' && raw.trim() !== '')) ? Number(raw) : NaN;
const value = Number.isFinite(v) ? v : null;
flow.set('cheapestHourDessSoc', { value: value, at: Date.now() });
node.status(value === null ? { fill: 'grey', shape: 'ring', text: 'unknown' } : { fill: 'green', shape: 'dot', text: value.toFixed(1) + '%' });
return null;
